#include "modules/fem_system_api.h"
#include "runtime/thread_budget.hpp"
#include <algorithm>
#include <atomic>
#include <cmath>
#include <cstring>
#include <iostream>
#include <memory>
#include <vector>
namespace {
unsigned checks=0,failures=0;void verify(bool okay,const char* text){++checks;if(!okay){++failures;std::cerr<<"FAIL "<<text<<'\n';}}
struct Host {std::shared_ptr<std::atomic_bool> cancel=std::make_shared<std::atomic_bool>(false);penta::runtime::ParallelStatistics stats;static int cancelled(void* raw){return static_cast<Host*>(raw)->cancel->load();}static int charge(void*,uint64_t,char*,uint64_t){return 0;}static int parallel(void* raw,uint64_t n,uint64_t cost,penta_numeric_range_task_v1 fn,void* data,char* error,uint64_t cap){auto& self=*static_cast<Host*>(raw);std::string text;const auto status=penta::runtime::ThreadBudget::instance().run(n,cost,fn,data,{4,1},self.cancel,self.stats,text);if(error&&cap){std::strncpy(error,text.c_str(),cap-1);error[cap-1]=0;}return status;}};
struct Model {unsigned mode=0;double time=0;bool stop=false;unsigned samples=0;static int clock(void* raw,double t,char*,uint64_t){static_cast<Model*>(raw)->time=t;return 0;}static int reaction(void* raw,const double* state,uint32_t c,const double*,uint32_t,double* output,double* jac,char*,uint64_t){const auto& m=*static_cast<Model*>(raw);for(unsigned i=0;i<c;++i){output[i]=m.mode==0?1000*state[i]*state[i]*state[i]:m.mode==3?state[i]:0;if(jac)for(unsigned j=0;j<c;++j)jac[i*c+j]=i==j?(m.mode==0?3000*state[i]*state[i]:m.mode==3?1:0):0;}return 0;}static int forcing(void* raw,const double* point,uint32_t,double* value,uint64_t,char*,uint64_t){const auto& m=*static_cast<Model*>(raw);value[0]=m.mode==1?-1-4*point[0]-2*m.time:m.mode==2?1:0;return 0;}static int initial(void* raw,const double* point,uint32_t,double* value,uint64_t,char*,uint64_t){const auto& m=*static_cast<Model*>(raw);value[0]=m.mode==1?point[0]*point[0]:m.mode==2?point[0]:1;return 0;}static int diffusion(void* raw,const double* point,uint32_t,double* value,uint64_t,char*,uint64_t){const auto& m=*static_cast<Model*>(raw);value[0]=1+point[0]+m.time;return 0;}static int boundary(void* raw,uint64_t,const double* point,const double* normal,uint32_t,double* value,double* alpha,char*,uint64_t){const auto& m=*static_cast<Model*>(raw);if(m.mode==1)value[0]=point[0]*point[0]+m.time;else if(m.mode==2){*alpha=1+m.time;value[0]=.2*normal[0]+*alpha*(point[0]+m.time);}else value[0]=0;return 0;}static int geometry(void*,const double* uv,uint32_t,double* point,double* jac,char*,uint64_t){point[0]=uv[0];point[1]=uv[1];point[2]=uv[0]*uv[0]+uv[1]*uv[1];if(jac){jac[0]=1;jac[1]=0;jac[2]=0;jac[3]=1;jac[4]=2*uv[0];jac[5]=2*uv[1];}return 0;}static int sample(void* raw,double time,const double*,uint64_t,uint32_t,char*,uint64_t){auto& self=*static_cast<Model*>(raw);++self.samples;return self.stop&&time>=.01?1:0;}};
struct Output {int status=0;penta_fem_time_result_v1 report{};std::vector<double> points,values,visPoints,visValues,times,series;std::vector<uint64_t> faces;std::string error;};
Output run(Model& model,unsigned order=2,bool adaptive=false,bool curved=false){std::vector<double> uv{0,0,1,0,1,1,0,1},points=curved?std::vector<double>{0,0,0,1,0,1,1,1,2,0,1,1}:uv;uint64_t triangles[]{1,2,3,1,3,4},boundary[]{1,2,1,2,3,2,3,4,3,4,1,4};penta_fem_system_boundary_condition_v1 conditions[4]{};for(unsigned j=0;j<4;++j){conditions[j].tag=j+1;conditions[j].kind=model.mode==1?PENTA_FEM_SYSTEM_DIRICHLET:model.mode==2?PENTA_FEM_SYSTEM_ROBIN:PENTA_FEM_SYSTEM_FLUX;conditions[j].alpha=model.mode==2?1:0;}penta_fem_time_request_v1 time{};time.struct_size=sizeof(time);time.adaptive=adaptive;time.t1=.02;time.time_step=.02;time.sample_step=.01;time.minimum_step=1e-9;time.maximum_step=.1;time.rtol=.002;time.atol=1e-8;time.max_steps=100000;time.clock_context=time.sample_context=&model;time.set_time=Model::clock;time.sample=Model::sample;auto& q=time.base;q.struct_size=sizeof(q);q.dimension=curved?3:2;q.components=1;q.order=order;q.visualization_refinement=4;q.vertices=4;q.triangles=2;q.boundaries=4;q.boundary_conditions=4;q.points=points.data();q.faces=triangles;q.boundary_tags=boundary;q.conditions=conditions;q.diffusion=model.mode==0?0:.2;q.rtol=1e-10;q.atol=1e-12;q.linear_tolerance=1e-11;q.max_seconds=60;q.max_newton=30;q.max_linear=1000;q.gmres_restart=40;q.max_work=1000000000;q.max_bytes=256*1024*1024;q.reaction=Model::reaction;q.reaction_context=&model;q.forcing=Model::forcing;q.forcing_context=&model;q.initial_field=Model::initial;q.initial_context=&model;q.boundary=Model::boundary;q.boundary_context=&model;if(model.mode==1){q.diffusion_field=Model::diffusion;q.diffusion_context=&model;}if(curved){q.geometry=Model::geometry;q.parameter_points=uv.data();}const uint64_t capacity=4+6*(order-1)+(order>=3?(order-1)*(order-2):0),samples=4;Output out;out.points.resize(capacity*q.dimension);out.values.resize(capacity);out.visPoints.resize(30*q.dimension);out.visValues.resize(30);out.faces.resize(96);out.times.resize(samples);out.series.resize(samples*capacity);auto& r=out.report;r.struct_size=sizeof(r);r.sample_capacity=samples;r.value_capacity=out.series.size();r.times=out.times.data();r.values=out.series.data();auto& f=r.field;f.struct_size=sizeof(f);f.dof_capacity=capacity;f.vertex_capacity=30;f.triangle_capacity=32;f.dof_coordinates=out.points.data();f.dof_values=out.values.data();f.visualization_coordinates=out.visPoints.data();f.visualization_values=out.visValues.data();f.visualization_faces=out.faces.data();Host owner;penta_fem_parallel_host_v1 host{};host.base={sizeof(host),PENTA_FEM_ABI_V1,&owner,Host::cancelled,Host::charge};host.threads_requested=host.threads_granted=4;host.parallel_for=Host::parallel;char error[1024]{};penta::runtime::ThreadBudget::instance().withReservation([&]{out.status=penta_fem_system_query_v1(PENTA_FEM_SYSTEM_ABI_V1)->time(&host.base,&time,&r,error,sizeof(error));});out.error=error;if(out.status)std::cerr<<"FEM time status "<<out.status<<": "<<error<<'\n';return out;}
}
int main(){Model cubic;auto nonlinear=run(cubic,3,true);verify(!nonlinear.status&&std::string(nonlinear.report.status)=="completed","adaptive implicit high-order nonlinear FEM completes");verify(!nonlinear.status&&std::abs(nonlinear.values[0]-1/std::sqrt(41.))<.004,"independent stiff cubic exact solution");verify(nonlinear.report.rejected_steps>0&&nonlinear.report.accepted_steps>2&&nonlinear.report.field.jacobian_evaluations>0,"adaptive error control and generated local Jacobian path");Model variable;variable.mode=1;auto dynamic=run(variable,2);verify(!dynamic.status&&dynamic.report.field.converged,"implicit time-dependent diffusion/Dirichlet data converge");double error=0;if(!dynamic.status)for(uint64_t node=0;node<dynamic.report.field.dofs;++node)error=std::max(error,std::abs(dynamic.values[node]-dynamic.points[2*node]*dynamic.points[2*node]-.02));verify(error<1e-8,"quadratic manufactured solution verifies time-dependent diffusion and consistent-mass Dirichlet derivatives");Model robin;robin.mode=2;auto mixed=run(robin,2);verify(!mixed.status&&mixed.report.field.converged,"time-varying Robin constraints work without an invented anchor");error=0;if(!mixed.status)for(uint64_t node=0;node<mixed.report.field.dofs;++node)error=std::max(error,std::abs(mixed.values[node]-mixed.points[2*node]-.02));verify(error<1e-8,"independent affine manufactured Robin solution");Model surface;surface.mode=3;auto curved=run(surface,3,false,true);verify(!curved.status&&curved.report.field.geometry_evaluations>0,"high-order transient curved-surface metric retained");if(!curved.status)verify(std::abs(curved.values[0]-1/std::pow(1.01,2))<1e-9,"curved-surface consistent mass preserves the independent constant decay mode");Model stopped;stopped.stop=true;auto partial=run(stopped,2,true);verify(!partial.status&&std::string(partial.report.status)=="user_stopped"&&partial.report.samples==2&&std::abs(partial.times[1]-.01)<1e-12,"time sample observer retains a complete stopped trajectory");std::cout<<checks<<" transient FEM checks, "<<failures<<" failures\n";return failures?1:0;}
